ON CONFLICT(entity_type, entity_id) DO NOTHING;

SELECT
  'seo-audit-20260922-' || replace(entity_type || '-' || entity_id, '-', ''),
  'seo-content-2026-09-22', 'system', 'seo_metadata', entity_type || '/' || entity_id, 'create',
  strftime('%Y-%m-%dT%H:%M:%fZ', 'now'),
  '{"source":"user-requested new New Zealand location and collections SEO after image review"}'
FROM seo_metadata
WHERE id LIKE 'seo-20260922-%'
ON CONFLICT(id) DO NOTHING;
