INSERT INTO seo_metadata (id, entity_type, entity_id, title, description, og_asset_id, canonical_url, updated_at) VALUES
  ('seo-20260922-location-new-zealand-26', 'location', '66518834-ee97-4e9a-9166-c110797afef0', '紐西蘭冬季攝影｜雪山、湖泊、峽灣與港灣 — UTOA Photography', '從奧克蘭的城市港灣與羅托路亞藍泉，走進南島的雪山、湖泊、峽灣與小鎮。這組冬季旅行攝影收錄皇后鎮、庫克山、蒂卡波、米佛峽灣等地的光線與沿途風景。', 'r2-cli-01895ac0609c6a5c', NULL, strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  ('seo-20260922-collection-queenstown', 'collection', '62a1344a-008b-451b-8afb-4c5239a86505', '皇后鎮冬季攝影｜瓦卡蒂普湖、雪山與山城夜景 — UTOA Photography', '從瓦卡蒂普湖畔望向覆雪山稜與皇后鎮街景，畫面收錄湖上的帆船、纜車視野、金色山光與入夜後的燈火。以遠近不同的高度，記錄冬日皇后鎮的湖光與山城輪廓。', 'r2-cli-1e80cc9970def306', NULL, strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  ('seo-20260922-collection-glenorchy', 'collection', '76575774-5632-47c7-98d0-171eaea0aba8', '格林諾奇攝影｜湖畔碼頭、雪峰與鄉間道路 — UTOA Photography', '格林諾奇的紅色木屋、靜止的湖面與遠方雪峰，構成南島冬日的開闊景色。作品也收錄湖畔碼頭、山谷雲霧、沿海公路和路邊相遇的狗狗，留下小鎮與自然之間的片刻。', 'r2-cli-72b7f34ab89f3fac', NULL, strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  ('seo-20260922-collection-auckland', 'collection', '9ba671fb-cecc-47e4-888e-368e404ad324', '奧克蘭攝影｜天空塔、港灣帆船與城市日落 — UTOA Photography', '從火山丘陵俯瞰奧克蘭的城市屋頂與天空塔，走到港灣邊的帆船碼頭與海岸。照片收錄街頭樂手、空中的海岸線與落日後的天色，呈現城市、海面與日常交會的視角。', 'r2-cli-74869da2a0d18ba9', NULL, strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  ('seo-20260922-collection-mount-cook', 'collection', '6f7c5462-b771-4a51-b5bf-e77bbddb09d4', '庫克山冬季攝影｜雪谷、冰河湖與銀河 — UTOA Photography', '庫克山腳下的積雪覆蓋山谷與步道，冰河湖被雪峰包圍。這組冬季影像記錄雲霧流動、吊橋、雪地足跡與夜空銀河，從白天的遼闊山景延伸至靜謐的星空。', 'r2-cli-0af9f23fe95e18cd', NULL, strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  ('seo-20260922-collection-tekapo', 'collection', '086b78dd-571a-4964-a989-e4810320493b', '蒂卡波冬雪攝影｜好牧羊人教堂、湖岸與雪景 — UTOA Photography', '雪落在蒂卡波湖畔的好牧羊人教堂與松林上，湖面、岸石和遠山逐漸隱入白霧。作品也收錄雪人、木屋與夜色裡亮起的窗光，記錄南島降雪當天細緻而安靜的景象。', 'r2-cli-01895ac0609c6a5c', NULL, strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  ('seo-20260922-collection-pukaki-tasman', 'collection', '3f355571-a48d-4a2a-9284-0044e7155093', '塔斯曼湖與普卡基湖攝影｜冰河雪峰與湖岸公路 — UTOA Photography', '塔斯曼湖與普卡基湖周邊，雪峰、冰河湖和冬季公路在陰晴之間展開。從湖面漂浮的冰塊、山脊輪廓到牧場與海岸道路，這組照片記錄南島旅途裡遙遠而清冷的尺度。', 'r2-cli-5d1373cf640ada87', NULL, strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  ('seo-20260922-collection-wanaka', 'collection', 'ee63d4ad-5762-442d-93f5-1cb6c3b8dd62', '瓦納卡攝影｜孤樹、湖面倒影與高地風景 — UTOA Photography', '瓦納卡湖中的孤樹在陰天水面上留下倒影，碼頭與山稜在光線變化裡安靜停留。作品也走進河岸、牧場、老建築與山路，收錄湖畔小鎮由近至遠的冬日風景。', 'r2-cli-fe1a1a38f368c922', NULL, strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  ('seo-20260922-collection-te-anau-milford', 'collection', 'a75163d7-914f-4fa8-a2b7-8d167ae22f86', '蒂阿瑙與米佛峽灣攝影｜湖光、峽灣瀑布與雪峰 — UTOA Photography', '蒂阿瑙湖的晨光與倒影，延伸到米佛峽灣的深色崖壁、巡航船和傾瀉的瀑布。這組作品收錄山谷、湖畔小船與峽灣水面，記錄南島西南方由寧靜到壯闊的自然景觀。', 'r2-cli-21710477814ab872', NULL, strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  ('seo-20260922-collection-christchurch', 'collection', '0bdfee3d-ef10-4149-b642-8a9fe92b6f6c', '基督城攝影｜石造建築、花園電車與港灣遠景 — UTOA Photography', '從石造建築與公園水面出發，走進基督城的街區、市集與復古電車。鏡頭也望向山丘、港灣、貨櫃碼頭與機場，將城市綠意、交通節奏與遠方海面收進同一段旅程。', 'r2-cli-7eeaffd50d3dddac', NULL, strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  ('seo-20260922-collection-kingston', 'collection', '532c4fc1-00f1-491b-a4e6-5180d827da19', '金士頓攝影｜雪山公路、牧場與湖岸風景 — UTOA Photography', '金士頓周邊的公路穿過覆雪山脈、牧場與深色湖面，低雲讓遠方山谷不斷改變層次。作品以沿途的道路、湖岸與農地為線索，記錄南島冬天開闊而帶有靜默感的旅程。', 'r2-cli-e93147c619041274', NULL, strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  ('seo-20260922-collection-arrowtown', 'collection', 'c86aad85-26e8-4f7d-bc33-75ce2c09f0a6', '箭鎮攝影｜石造街屋、淘金小鎮與冬日山景 — UTOA Photography', '箭鎮的石造屋舍、木造店鋪與老街招牌在晴朗冬日裡留住淘金小鎮的質感。作品沿著店面、博物館與巷弄移動，讓遠方山景與歷史建築一同成為南島旅程的一站。', 'r2-cli-685f7cde960f4dd9', NULL, strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  ('seo-20260922-collection-rotorua-blue-spring', 'collection', 'cf51c8dd-47aa-49e4-b3c9-4aa3cada0f8b', '藍泉與羅托路亞攝影｜碧綠湧泉、湖岸與水上飛機 — UTOA Photography', '藍泉的清澈水流穿過蕨類與水草，呈現層次分明的綠與藍。旅程接著來到羅托路亞湖岸，收錄起伏草坡、碼頭、陰雲水面與水上飛機，留下北島的自然色彩與天候變化。', 'r2-cli-b00ed82807834382', NULL, strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
